// Every Vow program runs top to bottom. print shows a value.
print("Hello, Vow!")

let name = "Ada"
let year = 2026
// ${...} puts a value inside a string
print("Hi ${name}, welcome to ${year}.")

// Plain braces are just text, handy for templates and JSON
print("{ this stays as written }")

// Types are inferred: you never write them.
fn area(w, h) {
  return w * h
}
print(area(3, 4))

// A fn that never says return gives back its last line.
fn greet(name) {
  "Hello, ${name}"
}
print(greet("Grace"))

// Functions work on any type that fits (generics, automatically).
fn first(xs) { return xs[0] }
print(first([10, 20, 30]))
print(first(["a", "b"]))

// Lambdas are small unnamed functions.
let double = x => x * 2
print(double(21))

let scores = [72, 95, 88, 61]

// Loops
let total = 0
for s in scores {
  total = total + s
}
print("total: ${total}")

// The same with the standard library
print(fold(scores, 0, (acc, s) => acc + s))
print(map(scores, s => s + 5))
print(filter(scores, s => s >= 80))
print(sort(scores))

// Maps have string keys
let ages = {"ada": 36, "alan": 41}
ages["grace"] = 85
for name in keys(ages) {
  print("${name} is ${ages[name]}")
}

// Vow has no null and no exceptions. Anything that can fail returns a Result:
// ok(value) or err(message), and the checker makes you handle both.
match num("42") {
  ok(n) => print("parsed ${n}")
  err(e) => print("not a number: ${e}")
}

match num("forty-two") {
  ok(n) => print("parsed ${n}")
  err(e) => print("not a number")
}

// Inside a fn, ? unwraps ok or returns the err to the caller.
fn addStrings(a, b) {
  let x = num(a)?
  let y = num(b)?
  return ok(x + y)
}
print(addStrings("2", "3"))
print(addStrings("2", "oops"))

struct Item { name, price, qty }

let cart = [
  Item { name: "pen", price: 1.5, qty: 4 },
  Item { name: "book", price: 12, qty: 1 },
  Item { name: "mug", price: 8, qty: 2 }
]

for it in sortBy(cart, it => it.price) {
  print("${it.name}: ${it.price * it.qty}")
}

// match also compares plain values; _ catches everything else
fn label(qty) {
  match qty {
    1 => "single"
    2 => "pair"
    _ => "bulk"
  }
}
print(label(cart[0].qty))

let text = "The quick  brown fox\tjumps over the lazy dog"

// words splits on any whitespace
let ws = words(text)
print(len(ws))

// Regex patterns go in backtick strings (no escaping needed)
print(matches("2026-10-08", `^\d{4}-\d{2}-\d{2}$`))
print(findAll("call 555-0100 or 555-0199", `\d{3}-\d{4}`))
match find("user=ada", `(\w+)=(\w+)`) {
  ok(m) => print("key ${m[1]}, value ${m[2]}")
  err(e) => print(e)
}
print(replaceAll("a-b-c", `-`, " + "))
print(upper(ws[1]))

let raw = `{"name": "Ada", "langs": ["vow", "ts"], "admin": true}`

match parseJson(raw) {
  ok(user) => {
    print(field(user, "name"))
    for lang in jsonList(field(user, "langs")) {
      print("knows ${lang}")
    }
    if truthy(field(user, "admin")) { print("is an admin") }
    // a missing field is a json null, not a crash
    print(isNull(field(user, "email")))
  }
  err(e) => print("bad JSON: ${e}")
}

// toJson turns Vow values (structs, maps, lists) into JSON text
struct Summary { ok, count }
print(toJson(Summary { ok: true, count: 3 }))

// expects: what callers must guarantee. ensures: what the fn promises back.
fn safeSqrtFloor(n) expects n >= 0 ensures result >= 0 {
  return floor(sqrt(n))
}
print(safeSqrtFloor(17))

// Breaking a contract stops the program and blames the right side.
fn withdraw(balance, amount) expects amount <= balance {
  return balance - amount
}
print(withdraw(100, 30))

// Vow even proves some broken calls before running: try uncommenting this line.
// print(withdraw(100, 500))

// When the bad value only shows up at runtime, the contract catches it then,
// and the error says the bug is in the CALLER, not in withdraw.
match num("500") {
  ok(amount) => print(withdraw(100, amount))
  err(e) => print(e)
}

// A fn that touches the network, files or environment must say so with uses.
// Anyone reading the signature knows exactly what it can reach.
fn fetchQuote(symbol) uses net {
  return httpGet("https://example.com/quote?s=${symbol}")
}

fn average(xs) {
  return sum(xs) / len(xs)
}

print(average([3, 4, 5]))
// In the browser playground network calls return an err; in the CLI they really run.
match fetchQuote("ACN") {
  ok(body) => print("got ${len(body)} bytes")
  err(e) => print("request failed: ${e}")
}

